#define MAXN 200005

int n;
int ax[MAXN], ay[MAXN]; // red
int cx[MAXN], cy[MAXN]; // blue

int cmp_red(const void *a, const void *b) {
    int i = *(int*)a, j = *(int*)b;
    return ax[j] - ax[i]; // descending x
}
int cmp_blue(const void *a, const void *b) {
    int i = *(int*)a, j = *(int*)b;
    return cx[j] - cx[i]; // descending x
}

// BIT for minimum query? We need: given d values, find min d > b_i
// Use a sorted structure. In C, let's use a simple sorted array with removal.

int dy[MAXN]; // available blue d values, sorted
int sz;

int find_min_gt(int val) {
    // binary search for first element > val
    int lo = 0, hi = sz - 1, res = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (dy[mid] > val) { res = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    return res;
}

void insert_sorted(int val) {
    int pos = sz++;
    // find insertion point
    int lo = 0, hi = sz - 2;
    while (lo <= hi) { int mid=(lo+hi)/2; if(dy[mid]<=val) lo=mid+1; else hi=mid-1; }
    memmove(&dy[lo+1], &dy[lo], (sz-1-lo)*sizeof(int));
    dy[lo] = val;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d%d", &ax[i], &ay[i]);
    for (int i = 0; i < n; i++) scanf("%d%d", &cx[i], &cy[i]);
    int ri[MAXN], bi[MAXN];
    for (int i=0;i<n;i++) ri[i]=bi[i]=i;
    qsort(ri,n,sizeof(int),cmp_red);
    qsort(bi,n,sizeof(int),cmp_blue);
    sz=0; int ans=0, bp=0;
    for (int i=0;i<n;i++) {
        int r=ri[i];
        while (bp<n && cx[bi[bp]]>ax[r]) { insert_sorted(cy[bi[bp]]); bp++; }
        int pos=find_min_gt(ay[r]);
        if (pos>=0) { ans++; memmove(&dy[pos],&dy[pos+1],(--sz-pos)*sizeof(int)); }
    }
    printf("%d\n",ans);
}

import java.util.*;
