public class Main {
    static int N;
    static boolean[][] adj;
    static int[] matchL, matchR;
    static int[] dist;
    static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        N = Integer.parseInt(br.readLine().trim());

        int[] a = new int[N], b = new int[N];
        int[] c = new int[N], d = new int[N];

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            a[i] = Integer.parseInt(st.nextToken());
            b[i] = Integer.parseInt(st.nextToken());
        }
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            c[i] = Integer.parseInt(st.nextToken());
            d[i] = Integer.parseInt(st.nextToken());
        }

        adj = new boolean[N][N];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (a[i] < c[j] && b[i] < d[j])
                    adj[i][j] = true;

        matchL = new int[N];
        matchR = new int[N];
        Arrays.fill(matchL, -1);
        Arrays.fill(matchR, -1);
        dist = new int[N];

        int result = 0;
        while (bfs()) {
            for (int u = 0; u < N; u++)
                if (matchL[u] == -1)
                    if (dfs(u)) result++;
        }

        System.out.println(result);
    }

    static boolean bfs() {
        Queue<Integer> queue = new LinkedList<>();
        for (int u = 0; u < N; u++) {
            if (matchL[u] == -1) {
                dist[u] = 0;
                queue.add(u);
            } else {
                dist[u] = INF;
            }
        }
        boolean found = false;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < N; v++) {
                if (adj[u][v]) {
                    int w = matchR[v];
                    if (w == -1) {
                        found = true;
                    } else if (dist[w] == INF) {
                        dist[w] = dist[u] + 1;
                        queue.add(w);
                    }
                }
            }
        }
        return found;
    }

    static boolean dfs(int u) {
        for (int v = 0; v < N; v++) {
            if (adj[u][v]) {
                int w = matchR[v];
                if (w == -1 || (dist[w] == dist[u] + 1 && dfs(w))) {
                    matchL[u] = v;
                    matchR[v] = u;
                    return true;
                }
            }
        }
        dist[u] = INF;
        return false;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        List<Point> points = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            points.add(new Point(sc.nextInt(), sc.nextInt(), 0)); // red
        }
        for (int i = 0; i < N; i++) {
            points.add(new Point(sc.nextInt(), sc.nextInt(), 1)); // blue
        }

        // Sort by x ascending, if same x then red before blue
        points.sort((p1, p2) -> {
            if (p1.x != p2.x) return Integer.compare(p1.x, p2.x);
            return Integer.compare(p1.type, p2.type);
        });

        // TreeMap to store y values of red points, with count
        TreeMap<Integer, Integer> redYMap = new TreeMap<>();
        int pairs = 0;

        for (Point p : points) {
            if (p.type == 0) {
                // red point
                redYMap.put(p.y, redYMap.getOrDefault(p.y, 0) + 1);
            } else {
                // blue point
                Integer key = redYMap.lowerKey(p.y);
                if (key != null) {
                    pairs++;
                    int count = redYMap.get(key);
                    if (count == 1) {
                        redYMap.remove(key);
                    } else {
                        redYMap.put(key, count - 1);
                    }
                }
            }
        }

        System.out.println(pairs);
    }

    static class Point {
        int x, y, type; // type 0 = red, 1 = blue
        Point(int x, int y, int type) {
            this.x = x;
            this.y = y;
            this.type = type;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        Point[] red = new Point[N];
        Point[] blue = new Point[N];

        for (int i = 0; i < N; i++) {
            red[i] = new Point(fs.nextInt(), fs.nextInt());
        }
        for (int i = 0; i < N; i++) {
            blue[i] = new Point(fs.nextInt(), fs.nextInt());
        }

        Arrays.sort(blue, Comparator.comparingInt(p -> p.x));

        boolean[] used = new boolean[N];
        int ans = 0;

        for (Point b : blue) {
            int bestIdx = -1;
            int bestY = -1;

            for (int i = 0; i < N; i++) {
                if (used[i]) continue;
                if (red[i].x < b.x && red[i].y < b.y) {
                    if (red[i].y > bestY) {
                        bestY = red[i].y;
                        bestIdx = i;
                    }
                }
            }

            if (bestIdx != -1) {
                used[bestIdx] = true;
                ans++;
            }
        }

        System.out.println(ans);
    }
}

