    multiset<int> available; // y-values of blues with x > current red's x
    int j = 0;
    int ans = 0;

    for(int i = 0; i < n; i++){
        // Add blues with x > red[i].x
        while(j < n && blue[j].first > red[i].first){
            available.insert(blue[j].second);
            j++;
        }
        // Find minimum y in available that is > red[i].second
        auto it = available.upper_bound(red[i].second);
        if(it != available.end()){
            ans++;
            available.erase(it);
        }
    }

    cout << ans << endl;
